import { get_video_metadata } from "../utils/commands.js";
export const DefaultSectionType = {
    NORMAL: "default.normal",
};
export class Section {
    type_;
    video;
    name;
    skip_animations;
    partial_movie_files;
    constructor(type_, video, name, skip_animations) {
        this.type_ = type_;
        this.video = video;
        this.name = name;
        this.skip_animations = skip_animations;
        this.partial_movie_files = [];
    }
    is_empty() {
        return this.partial_movie_files.length === 0;
    }
    get_clean_partial_movie_files() {
        return this.partial_movie_files.filter((el) => el !== null);
    }
    get_dict(sections_dir) {
        if (this.video === null) {
            const error = new Error(`Section '${this.name}' cannot be exported as dict, it does not have a video path assigned to it`);
            error.name = "ValueError";
            throw error;
        }
        // NOTE (interpreter scope): video probing / media export is out of scope;
        // get_video_metadata is a TODO stub and throws until it is ported.
        const video_metadata = get_video_metadata(`${sections_dir}/${this.video}`);
        return {
            name: this.name,
            type: this.type_,
            video: this.video,
            ...video_metadata,
        };
    }
    toRepr() {
        return `<Section '${this.name}' stored in '${this.video}'>`;
    }
}
